def round_half_to_even(n):
    """

       round up when n is even, round down when n is odd

        :param n:
        :return:
    """

    if n < 0:
        return -round_half_to_even(-n)
    elif n == 0:
        return 0
    elif n % 2 == 0:
        return n // 2
    else:
        return (n + 1) // 2

