def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    parts = s.split('.')
    indices = []
    for idx, part in enumerate(parts):
        if part.isnumeric():
            part = int(part)
        else:
            raise ValueError(f"Invalid version part '{part}'")
        indices.append(part)

    return tuple(indices)

