def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Create a set of all base classes, add a base class to it only once
    base_classes = set(x.__name__ for x in classes)

    # Iterate until no consecutive base classes remain
    done = False
    while not done:
        done = True
        for i in range(len(base_classes)):
            if i + 1 < len(base_classes):
                if base_classes[i] == base_classes[i+1]:
                    base_classes.remove(base_classes[i+1])
                    done = False

    # Convert the set back to a list
    base_classes_list = list(base_classes)

    return base_classes_list

