def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        raise ValueError("Path is required")

    existing_items = self.fs.list_contents()

    if existing_items and existing_items != self.fs.pypfs_contents() and existing_items != self.fs.fs_contents():
        logger.warn("Existing files in pyfs that are not present in the OCFL repository:" + "\t\t" + list(set(existing_items) - set(self.fs.pypfs_contents()) - set(self.fs.fs_contents())))
        return False

    if self.ocfl_root and not existing_items:
        logger.warn("No files have been stored in the OCFL repository. This may be okay for initial uploads, but can cause problems if used.")
        return False

    if self.ocfl_root and self.ocfl_version != self.collective_ocfl_version:
        logger.warn("The OCFL version stored in the repository does not match the collective OCFL version. This may cause problems if used.")
        return False

