def status_str(self, prefix=''):
        """Return string of validator status, with optional prefix."""
        status_lines = []

        # Add validators
        validator_report = self.validator_report
        if validator_report:
            status_lines.append(f"Validator Report: {validator_report}")

        # Add messages
        messages = self.messages
        if messages:
            status_lines.append(f"Messages:")
            for message in messages:
                status_lines.append(f"  - {message}")

        # Add generic info
        generic_info = self.get_generic_info()
        if generic_info:
            status_lines.append(f"Generic Info: {generic_info}")

        # Build the final status string
        if prefix:
            status_string = f"{prefix}Status:\n"
        else:
            status_string = "Status:\n"

        for line in status_lines:
            status_string += f"  - {line}\n"

        return status_string

