def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Check each digest in the manifest file
        for manifest_file in manifest_files:
            with open(manifest_file, 'r') as f:
                manifest = f.read()

            digests_in_manifest = set(digest[5:] for digest in manifest.split())  # Extract the digest values from the manifest

            # Check if all digests in digests_used set are present in digests_in_manifest set
            for digest in digests_used:
                if digest not in digests_in_manifest:
                    raise DigestIsNotPresentError(f"Digest {digest} is not present in the manifest file {manifest_file}")

