def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.get_inventory()
    for version_dir in version_dirs:
        inventory = self.get_inventory(version_dir)
        if inventory is None:
            if version_dir == "1":  # Starting from version 1
                if version_dir == "root":  # Root inventory
                    raise ValueError("Root inventory does not exist.")
                else:
                    raise ValueError("Inventory for version " + version_dir + " does not exist.")
            else:
                raise ValueError("Inventory for version " + version_dir + " does not exist.")
        current_digest = inventory.get_current_digest()
        root_digest = root_inventory.get_current_digest()
        if current_digest != root_digest:
            if current_digest is None:
                raise ValueError("No content digest found for version " + version_dir + ".")
            if root_digest is None:
                raise ValueError("No content digest found for root inventory.")
            raise ValueError("Content digests differ for inventory " + version_dir + ".")

