def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_arg dicts = {}
    remaining_args = []

    for request in sorted(subparsers.keys(), key=lambda x: subparsers[x].help):
        parser = subparsers[request]
        if request in confirmed_subparsers:
            # If the subparser has already been confirmed, add its arguments to the remaining list
            remaining_args.extend(parser.parse_known_args(unparsed_arguments)[1])
        else:
            # Otherwise, attempt to parse its arguments
            try:
                args, unknown_args = parser.parse_known_args(unparsed_arguments)
                # If the subparser parsed at least one argument, add its parsed information to the result dictionary
                parsed_arg_dicts[request] = args
            except Exception as e:
                # If the subparser failed to parse, add its arguments back to the remaining list for further review
                remaining_args.extend(parser.parse_known_args(unparsed_arguments)[1])

    # Add any remaining arguments that were not claimed by any parser to the result dictionary
    for arglist in remaining_args:
        if len(arglist) > 1:
            result[arglist[0]] = arglist[1:]

    return parsed_arg_dicts, remaining_args

