    """Remove and return the `(key, value)` pair least frequently used."""
    if not self.decache:
        return self.popitem_last()

    if len(self) <= 1:
        return self.popitem_last()

    for k, v in self.items():
        self._counts[k] = 0

    least_used = None
    min_count = float('inf')

    for k, v in self._counts.items():
        if v < min_count:
            min_count = v
            least_used = k

    self._counts.pop(least_used)
    return least_used, self.pop(least_used)

